#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MFP-3 ONE FILE v1.14 — ADAPTIVE FUSION LAB
===========================================

Mantiene todo v1.13 y añade un laboratorio de fusión:

- v1.7-FROZEN = motor principal de retorno.
- Synergy v1.13 = motor defensivo / confirmación.

La v1.14 NO modifica v1.7.
Sólo prueba, de manera walk-forward, cuánto capital histórico habría convenido
asignar a cada motor usando únicamente información pasada.

Metodología:
- mezcla v1.7 + Synergy;
- rebalanceo mensual;
- pesos candidatos predefinidos;
- varias ventanas de entrenamiento;
- selección por utilidad pasada;
- ensemble de los mejores candidatos;
- histéresis para evitar cambios bruscos;
- comparación contra v1.7 y benchmark en la MISMA ventana.

Uso:
    py mfp3_onefile_v1_14.py
    py mfp3_onefile_v1_14.py --fusion
    py mfp3_onefile_v1_14.py --install
    py mfp3_onefile_v1_14.py --status

No ejecuta operaciones reales.
"""

from __future__ import annotations

import argparse
import base64
import json
import math
import os
import subprocess
import sys
import zlib
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

V113_B64 = """"""

def embedded_source(blob: str) -> str:
    return zlib.decompress(base64.b64decode(blob)).decode("utf-8")

V113_SOURCE = embedded_source(V113_B64)

ROOT = Path(".")
LAB = ROOT / "mfp3_fusion_lab"
LAB.mkdir(exist_ok=True)

V17_PORT = ROOT / "mfp3_output_v17" / "portfolio_daily.csv"
SYNERGY_PORT = ROOT / "mfp3_synergy_lab" / "synergy_portfolio.csv"

FUSION_DAILY = LAB / "fusion_daily.csv"
FUSION_DECISIONS = LAB / "fusion_decisions.csv"
FUSION_METRICS = LAB / "fusion_metrics.csv"
FUSION_STATE = LAB / "fusion_state.json"

INITIAL_CAPITAL = 10_000_000.0
TASK_NAME = "MFP3_ONEFILE_V114_DAILY"
RUN_EVERY_DAYS = 14

# Weight means allocation to v1.7; remainder goes to Synergy.
V17_WEIGHTS = [0.50, 0.67, 0.75, 0.85, 1.00]
TRAIN_WINDOWS = [126, 252, 504]
TOP_K = 3

# Hysteresis: do not change allocation unless new target differs materially.
WEIGHT_HYSTERESIS = 0.08

# ---------------------------------------------------------------------
# Run v1.13
# ---------------------------------------------------------------------

def run_v113(args):
    old = sys.argv[:]
    try:
        sys.argv = ["mfp3_v113_embedded.py"]
        if args.full:
            sys.argv.append("--full")

        g = {
            "__name__": "mfp3_v113_embedded",
            "__file__": "<embedded:v1.13>",
            "__builtins__": __builtins__,
        }
        exec(compile(V113_SOURCE, g["__file__"], "exec"), g, g)
        g["main"]()
    finally:
        sys.argv = old

# ---------------------------------------------------------------------
# Scheduler
# ---------------------------------------------------------------------

def install_this_file():
    if os.name != "nt":
        raise SystemExit("--install sólo funciona en Windows.")

    script = str(Path(__file__).resolve())
    python = str(Path(sys.executable).resolve())
    action = f'"{python}" "{script}"'

    p = subprocess.run(
        [
            "schtasks", "/Create",
            "/TN", TASK_NAME,
            "/TR", action,
            "/SC", "DAILY",
            "/ST", "18:30",
            "/F",
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )

    if p.returncode != 0:
        print(p.stdout)
        print(p.stderr)
        raise SystemExit("No se pudo instalar la tarea.")

    print(p.stdout.strip())
    print("Instalado: v1.14 se ejecutará diariamente a las 18:30.")

def uninstall_this_file():
    if os.name != "nt":
        raise SystemExit("--uninstall sólo funciona en Windows.")

    p = subprocess.run(
        ["schtasks", "/Delete", "/TN", TASK_NAME, "/F"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    print((p.stdout or p.stderr).strip())

# ---------------------------------------------------------------------
# Metrics
# ---------------------------------------------------------------------

def perf(ret):
    r = pd.Series(ret).fillna(0.0)

    if len(r) == 0:
        return {
            "total_return": 0.0,
            "cagr": 0.0,
            "sharpe": 0.0,
            "max_drawdown": 0.0,
            "ann_vol": 0.0,
        }

    curve = (1 + r).cumprod()
    total = float(curve.iloc[-1] - 1.0)
    years = max(len(r) / 252.0, 1 / 252.0)
    cagr = float(curve.iloc[-1] ** (1 / years) - 1.0)
    vol = float(r.std() * np.sqrt(252))
    sharpe = float(r.mean() * 252 / vol) if vol > 1e-12 else 0.0
    dd = curve / curve.cummax() - 1.0

    return {
        "total_return": total,
        "cagr": cagr,
        "sharpe": sharpe,
        "max_drawdown": float(dd.min()),
        "ann_vol": vol,
    }

def utility(ret):
    p = perf(ret)

    # Fusion should improve risk-adjusted performance, not just raw return.
    score = (
        p["sharpe"]
        + 0.35 * p["cagr"]
        - 0.55 * abs(p["max_drawdown"])
    )

    return score, p

# ---------------------------------------------------------------------
# Load aligned engines
# ---------------------------------------------------------------------

def load_engines():
    if not V17_PORT.exists():
        raise RuntimeError(
            "Falta mfp3_output_v17/portfolio_daily.csv"
        )

    if not SYNERGY_PORT.exists():
        raise RuntimeError(
            "Falta mfp3_synergy_lab/synergy_portfolio.csv. "
            "Ejecuta primero v1.13."
        )

    v17 = pd.read_csv(
        V17_PORT,
        index_col=0,
        parse_dates=True,
    ).sort_index()

    syn = pd.read_csv(
        SYNERGY_PORT,
        index_col=0,
        parse_dates=True,
    ).sort_index()

    if "portfolio_net_ret" not in v17.columns:
        raise RuntimeError(
            "portfolio_daily.csv v1.7 no contiene portfolio_net_ret."
        )

    if "strategy_ret" not in syn.columns:
        raise RuntimeError(
            "synergy_portfolio.csv no contiene strategy_ret."
        )

    common = v17.index.intersection(syn.index)

    if len(common) < 500:
        raise RuntimeError(
            "Muy pocos días comunes entre v1.7 y Synergy."
        )

    x = pd.DataFrame(index=common)
    x["v17_ret"] = pd.to_numeric(
        v17.loc[common, "portfolio_net_ret"],
        errors="coerce",
    ).fillna(0.0)

    x["synergy_ret"] = pd.to_numeric(
        syn.loc[common, "strategy_ret"],
        errors="coerce",
    ).fillna(0.0)

    if "benchmark_ret" in syn.columns:
        x["benchmark_ret"] = pd.to_numeric(
            syn.loc[common, "benchmark_ret"],
            errors="coerce",
        ).fillna(0.0)
    elif "benchmark_ret" in v17.columns:
        x["benchmark_ret"] = pd.to_numeric(
            v17.loc[common, "benchmark_ret"],
            errors="coerce",
        ).fillna(0.0)
    else:
        x["benchmark_ret"] = 0.0

    return x

# ---------------------------------------------------------------------
# Candidate evaluation
# ---------------------------------------------------------------------

def blend_returns(frame, w):
    return (
        float(w) * frame["v17_ret"]
        + (1.0 - float(w)) * frame["synergy_ret"]
    )

def evaluate_candidates(train):
    rows = []

    for window in TRAIN_WINDOWS:
        z = train.tail(window)

        if len(z) < min(100, window // 2):
            continue

        for w in V17_WEIGHTS:
            r = blend_returns(z, w)
            score, p = utility(r)

            # Prefer stable candidates with acceptable participation in v1.7.
            # Small penalty for moving too far from Champion.
            champion_distance_penalty = 0.03 * (1.0 - w)

            rows.append({
                "window": window,
                "v17_weight": w,
                "score": score - champion_distance_penalty,
                "raw_utility": score,
                "return": p["total_return"],
                "cagr": p["cagr"],
                "sharpe": p["sharpe"],
                "drawdown": p["max_drawdown"],
            })

    return pd.DataFrame(rows)

def ensemble_target_weight(tab):
    if tab.empty:
        return 1.0, pd.DataFrame()

    top = tab.sort_values(
        ["score", "sharpe"],
        ascending=False,
    ).head(TOP_K).copy()

    s = top["score"].values.astype(float)
    s = s - np.max(s)

    # Softmax over top candidates.
    exp = np.exp(s / 0.10)
    exp = exp / exp.sum()

    top["ensemble_weight"] = exp

    target = float(
        np.sum(
            top["v17_weight"].values
            * top["ensemble_weight"].values
        )
    )

    return target, top

# ---------------------------------------------------------------------
# Walk-forward monthly fusion
# ---------------------------------------------------------------------

def monthly_rebalance_dates(index):
    s = pd.Series(index=index, data=1)
    return s.groupby(
        [index.year, index.month]
    ).head(1).index

def run_fusion():
    x = load_engines()
    rebalance_dates = set(monthly_rebalance_dates(x.index))

    # Need prior history before first choice.
    min_train = 126

    current_weight = 1.0
    weights = pd.Series(index=x.index, dtype=float)
    decisions = []

    for i, dt in enumerate(x.index):
        if i < min_train:
            weights.loc[dt] = current_weight
            continue

        if dt in rebalance_dates:
            train = x.iloc[:i]

            tab = evaluate_candidates(train)
            target, top = ensemble_target_weight(tab)

            # Hysteresis: reduce allocation churn.
            if abs(target - current_weight) >= WEIGHT_HYSTERESIS:
                new_weight = target
            else:
                new_weight = current_weight

            decisions.append({
                "date": dt,
                "previous_v17_weight": current_weight,
                "target_v17_weight": target,
                "applied_v17_weight": new_weight,
                "synergy_weight": 1.0 - new_weight,
                "best_score": (
                    float(top.iloc[0]["score"])
                    if len(top) else np.nan
                ),
                "best_window": (
                    int(top.iloc[0]["window"])
                    if len(top) else np.nan
                ),
                "best_candidate_v17_weight": (
                    float(top.iloc[0]["v17_weight"])
                    if len(top) else np.nan
                ),
            })

            current_weight = new_weight

        weights.loc[dt] = current_weight

    weights = weights.ffill().fillna(1.0)

    out = x.copy()
    out["v17_weight"] = weights
    out["synergy_weight"] = 1.0 - weights

    out["fusion_ret"] = (
        out["v17_weight"] * out["v17_ret"]
        + out["synergy_weight"] * out["synergy_ret"]
    )

    out["capital_fusion"] = (
        INITIAL_CAPITAL
        * (1 + out["fusion_ret"]).cumprod()
    )

    out["capital_v17"] = (
        INITIAL_CAPITAL
        * (1 + out["v17_ret"]).cumprod()
    )

    out["capital_synergy"] = (
        INITIAL_CAPITAL
        * (1 + out["synergy_ret"]).cumprod()
    )

    out["capital_benchmark"] = (
        INITIAL_CAPITAL
        * (1 + out["benchmark_ret"]).cumprod()
    )

    metrics = pd.DataFrame([
        {
            "name": "ADAPTIVE_FUSION_CHALLENGER",
            **perf(out["fusion_ret"]),
        },
        {
            "name": "V17_REFERENCE_COMMON_WINDOW",
            **perf(out["v17_ret"]),
        },
        {
            "name": "SYNERGY_REFERENCE_COMMON_WINDOW",
            **perf(out["synergy_ret"]),
        },
        {
            "name": "BENCHMARK_COMMON_WINDOW",
            **perf(out["benchmark_ret"]),
        },
    ])

    decisions_df = pd.DataFrame(decisions)

    out.to_csv(
        FUSION_DAILY,
        encoding="utf-8-sig",
    )
    decisions_df.to_csv(
        FUSION_DECISIONS,
        index=False,
        encoding="utf-8-sig",
    )
    metrics.to_csv(
        FUSION_METRICS,
        index=False,
        encoding="utf-8-sig",
    )

    FUSION_STATE.write_text(
        json.dumps(
            {
                "last_completed_utc":
                    datetime.now(timezone.utc).isoformat(timespec="seconds"),
                "version": "v1.14",
                "latest_v17_weight":
                    float(out["v17_weight"].iloc[-1]),
                "latest_synergy_weight":
                    float(out["synergy_weight"].iloc[-1]),
            },
            indent=2,
        ),
        encoding="utf-8",
    )

    return out, decisions_df, metrics

# ---------------------------------------------------------------------
# Cadence
# ---------------------------------------------------------------------

def fusion_due(force=False):
    if force or not FUSION_STATE.exists():
        return True

    try:
        s = json.loads(
            FUSION_STATE.read_text(encoding="utf-8")
        )

        last = pd.Timestamp(s["last_completed_utc"])

        if last.tzinfo is None:
            last = last.tz_localize("UTC")
        else:
            last = last.tz_convert("UTC")

        return (
            pd.Timestamp.now(tz="UTC") - last
        ).days >= RUN_EVERY_DAYS

    except Exception:
        return True

# ---------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------

def main():
    p = argparse.ArgumentParser()
    p.add_argument("--fusion", action="store_true")
    p.add_argument("--install", action="store_true")
    p.add_argument("--uninstall", action="store_true")
    p.add_argument("--status", action="store_true")
    p.add_argument("--full", action="store_true")
    args = p.parse_args()

    if args.install:
        install_this_file()
        return

    if args.uninstall:
        uninstall_this_file()
        return

    if args.status:
        print("\nMFP-3 v1.14 STATUS")
        print("Fusion Lab:", LAB.resolve())
        print("Fusion due:", fusion_due(False))
        print("Metrics:", FUSION_METRICS.exists())
        print("Decisions:", FUSION_DECISIONS.exists())
        return

    print("\n" + "=" * 96)
    print("MFP-3 ONE FILE v1.14 — ADAPTIVE FUSION LAB")
    print("=" * 96)

    # Keep complete chain alive.
    run_v113(args)

    if fusion_due(args.fusion):
        print(
            "\n[v1.14] Probando fusión walk-forward v1.7 + Synergy..."
        )

        out, decisions, metrics = run_fusion()

        print("\n" + "=" * 96)
        print("ADAPTIVE FUSION — RESULTADO")
        print("=" * 96)

        with pd.option_context(
            "display.max_columns", None,
            "display.width", 190,
        ):
            print(metrics)

        print(
            "\nCapital Fusion:",
            f"${out['capital_fusion'].iloc[-1]:,.0f} CLP"
        )
        print(
            "Capital v1.7 misma ventana:",
            f"${out['capital_v17'].iloc[-1]:,.0f} CLP"
        )
        print(
            "Capital Synergy misma ventana:",
            f"${out['capital_synergy'].iloc[-1]:,.0f} CLP"
        )
        print(
            "Capital Benchmark:",
            f"${out['capital_benchmark'].iloc[-1]:,.0f} CLP"
        )

        print(
            "\nPeso actual aprendido:"
        )
        print(
            "  v1.7-FROZEN:",
            f"{out['v17_weight'].iloc[-1]:.1%}"
        )
        print(
            "  Synergy   :",
            f"{out['synergy_weight'].iloc[-1]:.1%}"
        )

        if len(decisions):
            print("\nÚltimos cambios de peso:")
            with pd.option_context(
                "display.max_columns", None,
                "display.width", 180,
            ):
                print(decisions.tail(8))

    else:
        print(
            "\n[v1.14] Fusion Lab ya está actualizado. "
            "Se repite automáticamente cada 14 días."
        )

    print(
        "\nAdaptive Fusion sigue siendo Challenger. "
        "No altera la cartera Forward de v1.7-FROZEN."
    )

if __name__ == "__main__":
    main()
